<template>
  <div class="client-utility-page sg-client-page">
    <PublicNavbar />
    <main class="sg-client-shell utility-shell">
      <button type="button" class="back-link" @click="$router.push({ name:'client-complaints' })"><AppIcon name="arrowLeft" :size="17" /> Khiếu nại của tôi</button>
      <section v-if="loading" class="sg-client-card utility-state"><span class="spinner"></span> Đang tải chi tiết...</section>
      <section v-else-if="error" class="sg-client-card utility-state" role="alert"><AppIcon name="alert" :size="20" /><span>{{ error }}</span><button type="button" class="sg-client-button" @click="load">Thử lại</button></section>
      <template v-else-if="complaint">
        <div class="detail-workspace">
        <section class="utility-header"><div><p class="sg-client-eyebrow">{{ typeLabel(complaint.complaint_type) }}</p><h1>Khiếu nại #{{ complaint.id }}</h1><p>{{ statusLabel(complaint.status) }} · {{ formatDate(complaint.created_at) }}</p></div><router-link v-if="complaint.booking_id || complaint.booking?.id" :to="{ name:'booking-detail', params:{ id: complaint.booking_id || complaint.booking.id } }" class="sg-client-button sg-client-button--primary"><AppIcon name="calendar" :size="16" /> Xem booking</router-link></section>
        <section class="sg-client-card complaint-detail-card"><div class="original-message"><strong>Nội dung đã gửi</strong><p>{{ complaint.content }}</p></div><div class="timeline"><article class="timeline-item"><span class="timeline-mark"></span><div><strong>Bạn đã gửi khiếu nại</strong><p>{{ complaint.content }}</p><small>{{ formatDate(complaint.created_at) }}</small></div></article><article v-for="item in timeline" :key="item.id" class="timeline-item"><span class="timeline-mark"></span><div><strong>{{ item.user?.id === complaint.customer_id ? 'Bạn' : (item.user?.full_name || 'Bộ phận hỗ trợ') }}</strong><p>{{ item.content }}</p><small>{{ formatDate(item.created_at) }}</small></div></article></div><form v-if="canReply" class="reply-form" @submit.prevent="submitReply"><label for="reply-content">Phản hồi</label><textarea id="reply-content" v-model.trim="replyContent" rows="4" maxlength="4000" placeholder="Nhập nội dung trao đổi..." :disabled="sending"></textarea><p v-if="replyError" class="field-error">{{ replyError }}</p><button type="submit" class="sg-client-button sg-client-button--primary" :disabled="sending || replyContent.length < 2"><AppIcon name="send" :size="16" /> {{ sending ? 'Đang gửi...' : 'Gửi phản hồi' }}</button></form><div v-else class="closed-note">Khiếu nại đã kết thúc, không thể gửi thêm phản hồi.</div></section>
        <aside class="sg-client-card detail-context-card">
          <div class="utility-card-heading"><span class="utility-card-icon"><AppIcon name="messageSquare" :size="18" /></span><div><p class="sg-client-eyebrow">Hồ sơ hỗ trợ</p><h2>Thông tin yêu cầu</h2></div></div>
          <div class="detail-context-status"><span>Trạng thái hiện tại</span><strong>{{ statusLabel(complaint.status) }}</strong></div>
          <dl class="detail-context-list"><div><dt>Loại yêu cầu</dt><dd>{{ typeLabel(complaint.complaint_type) }}</dd></div><div><dt>Mã booking</dt><dd>{{ complaint.booking_id ? `#${complaint.booking_id}` : 'Không gắn booking' }}</dd></div><div><dt>Ngày gửi</dt><dd>{{ formatDate(complaint.created_at) }}</dd></div></dl>
          <div class="detail-context-note"><AppIcon name="info" :size="16" /><span>Phản hồi mới nhất sẽ được thêm vào dòng thời gian bên trái.</span></div>
          <router-link v-if="complaint.booking_id || complaint.booking?.id" class="sg3-button sg3-button--secondary detail-context-action" :to="{ name:'booking-detail', params:{ id: complaint.booking_id || complaint.booking.id } }"><AppIcon name="calendar" :size="16" /> Mở booking liên quan</router-link>
        </aside>
        </div>
      </template>
    </main>
  </div>
</template>

<script>
import AppIcon from '../../components/AppIcon.vue';
import PublicNavbar from '../../components/PublicNavbar.vue';
import { complaintService } from '../../services/complaintService.js';
export default { name:'ClientComplaintDetail', components:{ AppIcon, PublicNavbar }, data(){return { complaint:null, timeline:[], loading:true, error:'', replyContent:'', replyError:'', sending:false }}, computed:{canReply(){return !['resolved','rejected','closed'].includes(this.complaint?.status)}}, mounted(){this.load()}, methods:{async load(){this.loading=true;this.error='';try{const response=await complaintService.get(this.$route.params.id);const payload=response.data||{};this.complaint=payload.complaint||null;this.timeline=payload.timeline||[]}catch(error){this.error=error.message||'Vui lòng thử lại.'}finally{this.loading=false}},async submitReply(){this.replyError='';this.sending=true;try{const response=await complaintService.reply(this.complaint.id,this.replyContent);this.timeline.push(response.data);this.replyContent='';this.complaint.status='processing'}catch(error){this.replyError=error.message||'Không thể gửi phản hồi.'}finally{this.sending=false}},typeLabel(type){return type==='venue'?'Khiếu nại cụm sân':'Khiếu nại hệ thống'},statusLabel(status){return {open:'Mới gửi',processing:'Đang xử lý',resolved:'Đã xử lý',rejected:'Từ chối',closed:'Đã đóng'}[status]||status||'Chưa cập nhật'},formatDate(value){return value?new Date(value).toLocaleString('vi-VN'):'-'}}};
</script>

