00}.detail-context-note{display:flex;gap:8px;padding:12px;border:1px solid #d9eee1;border-radius:10px;color:#64748b;font-size:12px;line-height:1.5}.detail-context-note svg{flex:none;color:#087642}.detail-context-action{width:100%;margin-top:15px}@media(max-width:820px){.detail-workspace{grid-template-columns:1fr}.detail-workspace .utility-header{grid-column:auto}.detail-context-card{order:2}}@media(max-width:720px){.utility-header{align-items:stretch;flex-direction:column}}
</style>
